import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { RootState, AppDispatch } from '../../store/store';
import { fetchAccounts } from '../../store/slices/accountsSlice';
import './Accounts.css';

const Accounts: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const { accounts, isLoading, error } = useSelector((state: RootState) => state.accounts);

  useEffect(() => {
    dispatch(fetchAccounts());
  }, [dispatch]);

  if (loading) {
    return (
      <div className="accounts">
        <div className="loading">Loading accounts data...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="accounts">
        <div className="error">Error loading accounts: {error}</div>
      </div>
    );
  }

  return (
    <div className="accounts">
      <h1>Trading Accounts</h1>
      
      <div className="accounts-summary">
        <div className="summary-card">
          <h3>Total Accounts</h3>
          <div className="summary-value">{accounts?.length || 0}</div>
        </div>
        <div className="summary-card">
          <h3>Active Accounts</h3>
          <div className="summary-value">
            {accounts?.filter(acc => acc.isActive).length || 0}
          </div>
        </div>
        <div className="summary-card">
          <h3>Symbols Traded</h3>
          <div className="summary-value">
            {new Set(accounts?.map(acc => acc.symbol)).size || 0}
          </div>
        </div>
      </div>

      <div className="accounts-table">
        <div className="table-header">
          <span>Account Name</span>
          <span>Symbol</span>
          <span>Total Trades</span>
          <span>First Trade</span>
          <span>Last Trade</span>
          <span>Status</span>
        </div>
        
        {accounts?.length ? (
          accounts.map((account, index) => (
            <div key={index} className="table-row">
              <span className="account-name">{account.name}</span>
              <span className="symbol-badge">{account.symbol}</span>
              <span>{account.totalTrades}</span>
              <span>
                {account.firstTradeDate 
                  ? new Date(account.firstTradeDate).toLocaleDateString()
                  : 'N/A'
                }
              </span>
              <span>
                {account.lastTradeDate 
                  ? new Date(account.lastTradeDate).toLocaleDateString()
                  : 'N/A'
                }
              </span>
              <span className={`status ${account.isActive ? 'active' : 'inactive'}`}>
                {account.isActive ? 'Active' : 'Inactive'}
              </span>
            </div>
          ))
        ) : (
          <div className="no-accounts">
            <h3>No Accounts Found</h3>
            <p>No trading accounts have been configured or imported yet.</p>
          </div>
        )}
      </div>

      {accounts?.length > 0 && (
        <div className="accounts-details">
          <h2>Account Details</h2>
          <div className="details-grid">
            {accounts.map((account, index) => (
              <div key={index} className="account-detail-card">
                <div className="card-header">
                  <h3>{account.name}</h3>
                  <span className={`status-indicator ${account.isActive ? 'active' : 'inactive'}`}>
                    {account.isActive ? 'Active' : 'Inactive'}
                  </span>
                </div>
                
                <div className="card-content">
                  <div className="detail-row">
                    <span>Symbol:</span>
                    <span className="symbol-badge">{account.symbol}</span>
                  </div>
                  <div className="detail-row">
                    <span>Total Trades:</span>
                    <span>{account.totalTrades}</span>
                  </div>
                  <div className="detail-row">
                    <span>Trading Period:</span>
                    <span>
                      {account.firstTradeDate && account.lastTradeDate
                        ? `${new Date(account.firstTradeDate).toLocaleDateString()} - ${new Date(account.lastTradeDate).toLocaleDateString()}`
                        : 'N/A'
                      }
                    </span>
                  </div>
                  <div className="detail-row">
                    <span>Days Active:</span>
                    <span>
                      {account.firstTradeDate && account.lastTradeDate
                        ? Math.ceil((new Date(account.lastTradeDate).getTime() - new Date(account.firstTradeDate).getTime()) / (1000 * 60 * 60 * 24))
                        : 'N/A'
                      }
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default Accounts;
